export const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function search(products,q){return products.filter(p=>normalize([p.name,p.code,p.brand,p.spec,p.shelf,p.level,p.box].join(' ')).includes(normalize(q)))}
export function move(db,id,type,amount,note,device){const p=db.products.find(p=>p.id===id);if(!p)throw Error('Producto no encontrado');if(!Number.isInteger(amount)||amount<0||(type!=='count'&&amount===0))throw Error('Usa una cantidad entera válida');if(!['in','out','count'].includes(type))throw Error('Movimiento inválido');const before=p.qty;const after=type==='count'?amount:before+(type==='in'?amount:-amount);if(after<0)throw Error('La salida supera las existencias');if(type==='count'&&!note.trim())throw Error('Indica el motivo del conteo');p.qty=after;db.events.unshift({id:crypto.randomUUID(),productId:id,name:p.name,type,before,after,delta:after-before,note,at:new Date().toISOString(),device,sync:'local'});return p;}
